import{_ as a,C as o,o as n,c as s,a6 as t,E as i}from"./chunks/framework.BBIckNDn.js";const w=JSON.parse('{"title":"ビデオゲーム史 — 遊び・ハード・作り方の変化をつなぐ","description":"遊び・ハード・制作・流通・保存をつなぐ概説と、1971〜2026年の代表作・ハード年表。","frontmatter":{"title":"ビデオゲーム史 — 遊び・ハード・作り方の変化をつなぐ","description":"遊び・ハード・制作・流通・保存をつなぐ概説と、1971〜2026年の代表作・ハード年表。","study":{"source":"新規執筆","kind":"本文草稿","status":"草稿","summary":"遊び・ハード・制作・流通・保存をつなぐ概説と、1971〜2026年の代表作・ハード年表。"}},"headers":[],"relativePath":"history/video-games.md","filePath":"history/video-games.md"}'),d={name:"history/video-games.md"};function l(h,e,p,f,m,c){const r=o("AnnualHighlights");return n(),s("div",null,[e[0]||(e[0]=t('<h1 id="ビデオゲーム史-—-遊び・ハード・作り方の変化をつなぐ" tabindex="-1">ビデオゲーム史 — 遊び・ハード・作り方の変化をつなぐ <a class="header-anchor" href="#ビデオゲーム史-—-遊び・ハード・作り方の変化をつなぐ" aria-label="Permalink to &quot;ビデオゲーム史 — 遊び・ハード・作り方の変化をつなぐ&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本文草稿と資料の範囲</p><p>主要な転換を選んだ概説です。地域別・ジャンル別の網羅と追加の査読は、今後の増補対象です。発売地域、発表・初公開・発売、原作と移植を区別します。</p><p>資料の参照日：2026-10-30。機種やコードの実機検証を示すものではありません。</p></div><h2 id="origins" tabindex="-1">1. 前史と研究室の遊び — 何を「ビデオゲーム」と呼ぶか <a class="header-anchor" href="#origins" aria-label="Permalink to &quot;1. 前史と研究室の遊び — 何を「ビデオゲーム」と呼ぶか {#origins}&quot;">​</a></h2><div class="study-source-prose"><p>ゲームの起源を考えるときは、電子装置で遊ぶこと、コンピュータでルールを計算すること、映像画面を使うこと、商品として売られることを分けたい。どれを条件にするかで、挙がる先駆例が変わる。「世界初」という一語より、何が新しかったのかを確かめる方が、この後の技術を理解しやすい。</p><p>1958年のTennis for Twoは、研究所の一般公開で、アナログコンピュータとオシロスコープを使って2人が遊んだ例である。現代のCPU上でゲームプログラムを動かす構成とは異なる。Brookhavenの回顧自身も先行例に触れており、本章も唯一の起源とは扱わない。<a href="https://www.bnl.gov/about/history/firstvideo.php" target="_blank" rel="noopener noreferrer">Brookhaven National Laboratory：The First Video Game?</a></p><p>Spacewar!では、1961年の構想から1962年にかけて、PDP-1で動くゲームが複数の人の実装・改良を通して形になった。ここでは、計算機の能力だけでなく、入力装置、画面、動きの計算、コードを共有する人々を一緒に見る。<a href="https://www.computerhistory.org/pdp-1/spacewar/" target="_blank" rel="noopener noreferrer">Computer History Museum：Spacewar!</a></p><p><strong>辞典への接続：</strong>アナログとデジタル、表示装置、入力、命令実行、シミュレーション、プログラムの共有。</p></div><h2 id="arcade" tabindex="-1">2. 1970年代 — 筐体とテレビが、遊ぶ場所を変える <a class="header-anchor" href="#arcade" aria-label="Permalink to &quot;2. 1970年代 — 筐体とテレビが、遊ぶ場所を変える {#arcade}&quot;">​</a></h2><div class="study-source-prose"><p>業務用機は、装置・操作・画面・支払い方を一つの商品として設計する。Computer Spaceは1971年、Pongは1972年の商業化の例である。研究施設の利用者に向けたデモと、初めて触る客が短時間で遊べる筐体では、操作の説明やゲームの長さにも異なる要求がある。<a href="https://www.computerhistory.org/timeline/graphics-games/" target="_blank" rel="noopener noreferrer">Computer History Museum：Graphics &amp; Games</a></p><p>同じ1972年にはMagnavox Odysseyが家庭のテレビで遊ぶ製品として登場した。画面だけですべてを表すのでなく、オーバーレイやカード等も組み合わせていた。家庭用機とアーケードは、一方がもう一方を置き換えた一本道としてではなく、場所と遊び方の異なる流れとして読む。<a href="https://americanhistory.si.edu/collections/object/nmah_1302004" target="_blank" rel="noopener noreferrer">Smithsonian：Magnavox Odyssey Video Game Unit, 1972</a></p><p>日本では、スペースインベーダーの1978年の発表から1979年にかけての広がりを、筐体や設置場所と結び付けて見られる。タイトーの回顧には喫茶店へのテーブル筐体の設置も記録されている。作品のルールと、遊びが人の集まる場所へ入る過程を併せて追う。<a href="https://www.taito.co.jp/70th/history" target="_blank" rel="noopener noreferrer">タイトー70周年：タイトーの歩み</a></p><p><strong>辞典への接続：</strong>専用回路、CPUを使う構成との違い、画面更新、入力応答、スコアと難易度、筐体・コントローラ。</p></div><h2 id="homes" tabindex="-1">3. 1980〜1990年代 — 家庭用・PC・携帯機と、作る人・遊ぶ人 <a class="header-anchor" href="#homes" aria-label="Permalink to &quot;3. 1980〜1990年代 — 家庭用・PC・携帯機と、作る人・遊ぶ人 {#homes}&quot;">​</a></h2><div class="study-source-prose"><p>1983年の日本でのファミコン発売は、カセットを入れ換えて複数の作品を遊ぶ家庭用機の具体例になる。任天堂の年表には、その後の他社ソフトメーカーの参入、ファミリーベーシック、専門誌や裏技の文化も記録されている。ハードの性能表に加えて、誰がソフトを作り、どう情報を知り、作品を選ぶかを見る必要がある。<a href="https://www.nintendo.com/jp/famicom/history/index.html" target="_blank" rel="noopener noreferrer">任天堂：ファミコン年表</a></p><p>同じ時期を北米から見ると、1983年以降の市場の落ち込みと、1985年のNES展開という別の経過がある。「1983年に世界のゲーム産業が崩壊した」と一括りにはできない。地域、プラットフォーム、流通を分けて読む。<a href="https://www.computerhistory.org/timeline/graphics-games/" target="_blank" rel="noopener noreferrer">Computer History Museum：Graphics &amp; Games</a></p><p>1989年のゲームボーイは、持ち運べる場面を考える例になる。電池、画面、重量、操作、遊ぶ時間をどう配分するかは、据置機と同じ問いではない。携帯機・家庭用機・PC・アーケードを並べると、性能の高低だけでは説明できない設計の選択が見えてくる。<a href="https://www.nintendo.co.jp/corporate/history/index.html" target="_blank" rel="noopener noreferrer">任天堂：会社の沿革</a></p><p>ジャンルも、アクション、RPG、アドベンチャー、対戦格闘、パズル、シミュレーション等を別の視点でたどりたい。長く保存する進行、短い対戦、文章を読む体験では、入力・時間・データ・画面に求めるものが異なる。各ジャンルの起源と地域別の展開は、本章から詳しい個別史へ分けて増補する。</p><p><strong>辞典への接続：</strong>ROM/RAM、セーブ、スプライト・タイル、音源、アセンブリ、開発用PC、配布媒体、ローカライズ。</p></div><h2 id="three-d" tabindex="-1">4. 1990年代 — 3D化は、絵だけでなく制作と操作を変える <a class="header-anchor" href="#three-d" aria-label="Permalink to &quot;4. 1990年代 — 3D化は、絵だけでなく制作と操作を変える {#three-d}&quot;">​</a></h2><div class="study-source-prose"><p>3D表現の歴史をPCのGPUだけで説明すると、アーケードや家庭用機の仕事が見えにくくなる。1993年のバーチャファイターは、MODEL1基板でポリゴンの人物を動かす業務用作品の例である。同じ年のDOOMは、PCの描画、レベルデータ、改造を考える別の入口になる。<a href="https://www.sega.jp/history/arcade/product/9122/" target="_blank" rel="noopener noreferrer">セガ・アーケードゲームヒストリー：バーチャファイター</a>、<a href="https://bethesda.net/en-US/news/doom-turns-22" target="_blank" rel="noopener noreferrer">Bethesda：DOOM Turns 22!</a></p><p>DOOMを「最初のFPS」や、現代と同じ全面的な3Dポリゴン描画として扱う必要はない。公開ソースを読むときは、原作の発売時点と、後年に公開・移植された実装を分ける。Quakeも、1996年の登場、後のOpenGL版やネットワーク向けの改良を別の出来事として追うと、描画と通信の変化を確かめやすい。<a href="https://github.com/id-Software/DOOM" target="_blank" rel="noopener noreferrer">id Software：DOOM公開ソース</a>、<a href="https://bethesda.net/en-US/news/celebrating-25-years-of-quake" target="_blank" rel="noopener noreferrer">Bethesda：Celebrating 25 years of Quake</a>、<a href="https://github.com/id-Software/Quake" target="_blank" rel="noopener noreferrer">id Software：Quake公開ソース</a></p><p>1994年に日本で発売されたPlayStationは、3D表現とCD-ROMを一緒に考える例になる。媒体に入る量と、実行時にRAMへ置ける量は別の制約である。モデル、画像、音声、映像をどう用意し、いつ読み込むかという問いが、制作ツール・圧縮・ストリーミングへつながる。<a href="https://www.playstation.com/en-us/playstation-history/1994-ps-one/" target="_blank" rel="noopener noreferrer">PlayStation：1994の歴史</a></p><p>3Dでは形状だけでなく、カメラ、奥行きの読み取り、照準、人物の動かし方も設計する。2D表現が不要になったのではなく、表現方法ごとに異なる作り方が併存していく。</p><p><strong>辞典への接続：</strong>メッシュ、座標変換、BSP、ラスタライズ、テクスチャ、カメラ、CDとI/O、モデル・UV・アニメーションの制作工程。</p></div><h2 id="online" tabindex="-1">5. 1990年代後半〜2000年代 — ネットワークと、ゲームを支える基盤 <a class="header-anchor" href="#online" aria-label="Permalink to &quot;5. 1990年代後半〜2000年代 — ネットワークと、ゲームを支える基盤 {#online}&quot;">​</a></h2><div class="study-source-prose"><p>ネットワークは、画面を描く以外にもゲームの条件を増やす。誰の状態を正しいとするか、入力や更新が遅れたときにどう見せるか、利用者の接続や退出をどう扱うかを決める必要がある。1998年に日本で発売されたDreamcastのモデム標準装備は、家庭用機と通信サービスをつなぐ例として読める。オンラインゲーム自体の起源という意味ではない。<a href="https://www.sega.jp/history/hard/dreamcast/" target="_blank" rel="noopener noreferrer">セガハード大百科：ドリームキャスト</a></p><p>描画側では、固定された処理と、プログラムを書けるシェーダの役割を分けて追いたい。NVIDIAの企業年表にある2001年のGeForce3導入は、PC向け製品史の具体的な一例である。専用基板や家庭用機の歴史も並べ、HLSL・GLSL、API、driver、GPUの役割へ接続する。<a href="https://www.nvidia.com/content/timeline/time_01.html" target="_blank" rel="noopener noreferrer">NVIDIA Corporate Timeline：2001</a></p><p>配信・更新の基盤も重要になる。Valveの公式冊子はSteamの2003年の公開を更新配信の目的と結び付けて説明している。ここから、配布物、パッチ、バージョン互換、ストア、コミュニティを同じ仕組みで扱うことの意味を考えられる。デジタル配信全体がここから始まった、という主張ではない。<a href="https://media.steampowered.com/apps/valve/2022/steamDeck_booklet_EN.pdf" target="_blank" rel="noopener noreferrer">Valve：Steam Deck Booklet</a></p><p><strong>辞典への接続：</strong>socket、遅延、サーバとクライアント、状態同期、認証、パッチ、ファイル検証、shader compiler、エンジンとmiddleware。</p></div><h2 id="mobile" tabindex="-1">6. 2000年代後半〜2010年代 — スマホ・ストア・継続運営 <a class="header-anchor" href="#mobile" aria-label="Permalink to &quot;6. 2000年代後半〜2010年代 — スマホ・ストア・継続運営 {#mobile}&quot;">​</a></h2><div class="study-source-prose"><p>2008年のApp Storeの登場は、携帯端末と、ソフトを探す・入手する・支払う仕組みを考える例になる。専用コントローラを前提にしないタッチ操作、小さな画面、中断と再開などを、アプリの設計に結び付けて読む。ただし携帯電話のゲームは2008年より前から存在し、スマホだけをモバイルゲーム史の起点にはしない。<a href="https://www.apple.com/newsroom/2018/07/app-store-turns-10/" target="_blank" rel="noopener noreferrer">Apple：The App Store turns 10</a></p><p>売り切り、追加コンテンツ、基本プレイ無料、定額制などの違いは、価格の違いだけでなく、開発・更新・運営とプレイヤーの関係を考える軸になる。2011年のTeam Fortress 2の基本プレイ無料化は販売方法の変更の一例であり、F2Pそのものの始まりではない。韓国などのPCオンラインゲームの流れも並行して扱う必要がある。<a href="https://store.steampowered.com/oldnews/5721?l=english" target="_blank" rel="noopener noreferrer">Valve：Team Fortress 2 is now Free to Play</a>、<a href="https://www.nexon.co.jp/en/ir/uploads/sokai20140325e.pdf" target="_blank" rel="noopener noreferrer">Nexon：2014年公式IR資料</a></p><p>運営するゲームでは、配布して終わる場合とは異なり、更新中のデータ互換、サーバ側の状態、障害、コミュニティ対応を継続して扱う。技術の章では、バージョン管理・観測・テスト・デプロイ・セーブデータの互換性へつなげる。どの方式が優れているかという順位ではなく、各方式が作品と遊びに何を要求するかを見る。</p><p><strong>辞典への接続：</strong>モバイルOS、入力・画面・電力、非同期処理、通信失敗、運用、データ形式、CI、計測。</p></div><h2 id="creation" tabindex="-1">7. 2010年代以降 — 作る・共有する・身体で遊ぶ <a class="header-anchor" href="#creation" aria-label="Permalink to &quot;7. 2010年代以降 — 作る・共有する・身体で遊ぶ {#creation}&quot;">​</a></h2><div class="study-source-prose"><p>ゲームを完成品として遊ぶことと、ゲームの中や周囲で何かを作ることは重なり合う。MinecraftはPC向け初公開を2009年、正式版を2011年としている。建築・共同作業・共有を考える事例になるが、MODやプレイヤー創作の始まりではない。DOOM等の前の節とつないで読むと、作り手と遊び手の境界をたどれる。<a href="https://www.minecraft.net/en-us/about-minecraft" target="_blank" rel="noopener noreferrer">Minecraft：What is Minecraft?</a></p><p>制作を支える側では、既存エンジン・ツール・教材を利用できる条件が変わる。2015年のUE4の無料利用への変更発表は、その一例として扱える。ただし当時の告知は、現在の料金・契約条件を示す資料ではない。インディーや小規模制作についても、エンジンだけでなく、配信、宣伝、コミュニティ、制作費を併せて読む必要がある。<a href="https://www.unrealengine.com/en-US/blog/ue4-is-free" target="_blank" rel="noopener noreferrer">Epic：If You Love Something, Set It Free</a></p><p>遊びの身体性も別の軸になる。2016年の北米でのPS VR発売発表は家庭向けVRの具体例で、頭の向き、表示、音、入力を体験として組み合わせる条件へつながる。2017年のNintendo Switchはテレビと携帯の利用場面を行き来する例になる。いずれも過去の試みを受けた製品で、VRや携帯ゲームの誕生そのものとは分ける。<a href="https://sony.mediaroom.com/2016-10-13-PlayStation-Makes-Virtual-Reality-Mainstream-With-Launch-Of-PlayStation-VR-Across-The-U-S-And-Canada" target="_blank" rel="noopener noreferrer">Sony：2016年の北米PS VR発売発表</a>、<a href="https://www.nintendo.co.jp/corporate/history/index.html" target="_blank" rel="noopener noreferrer">任天堂：会社の沿革</a></p><p>現代のゲームを読む際には、2D/3Dや大作/小規模に加え、配信・観戦、アクセシビリティ、プレイヤーの制作、コミュニティ、端末間の違いも調べたい。本稿はそれらを読み解く入口とし、最新機種や売上のランキングを歴史の結論にはしない。</p><p><strong>辞典への接続：</strong>エディタ・制作支援、アセットパイプライン、MOD、sandbox、VR/AR、立体視、追跡、入力遅延、アクセシビリティ。</p></div><h2 id="preservation" tabindex="-1">8. 保存と研究 — 動くゲームと、その周囲を残す <a class="header-anchor" href="#preservation" aria-label="Permalink to &quot;8. 保存と研究 — 動くゲームと、その周囲を残す {#preservation}&quot;">​</a></h2><div class="study-source-prose"><p>ビデオゲームは、実行ファイル一つだけで体験を再現できるとは限らない。実機や周辺機器、OS、driver、利用するサーバ、入力や表示の条件も関わる。映像で残せることと、実際に操作して調べられることにも違いがある。</p><p>米国議会図書館の保存推奨形式は、ソースや完成ビルドに加えて、必要な環境・文書・コンパイラ情報等を挙げている。重要なオンライン依存を再現できない場合の映像にも言及する。ここから、ゲーム史とコンパイラ・OS・ファイル形式・再現可能なビルドがつながる。<a href="https://www.loc.gov/preservation/resources/rfs/software-videogames.html" target="_blank" rel="noopener noreferrer">Library of Congress：Software and Video Games保存推奨形式</a></p><p>作品の歴史を調べるときは、パッケージ、マニュアル、当時の広告・雑誌、開発資料、ソース、プレイ記録、制作者や利用者の証言を並べたい。後年の回顧は当時の資料とは立場が異なり、メーカーの広報も、その企業から見た記録として読む。</p><p>本章の年表は、確認できた主要な転換を選んだ概説である。日本・北米の事例を軸にした初稿で、欧州の家庭用コンピュータ、韓国・中国等のオンライン/モバイル市場、各地域の制作・流通・プレイヤー文化は個別資料を増やして補いたい。技術の進歩だけで歴史を一本化しないことを、増補時にも保つ。</p><p><strong>辞典への接続：</strong>エミュレーション、バイナリ形式、依存関係、compiler/SDKの版、build、データ保存、サーバ依存、出典管理。</p></div><h2 id="milestones" tabindex="-1">主な出来事の年表 <a class="header-anchor" href="#milestones" aria-label="Permalink to &quot;主な出来事の年表 {#milestones}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>年・時期</th><th>地域・対象</th><th>出来事</th><th>読み取る観点・出典</th></tr></thead><tbody><tr><td>1958</td><td>米国・研究展示</td><td>Tennis for Two</td><td>アナログコンピュータとオシロスコープで対戦する先駆例。起源を一つに決める根拠にはしない。 <a href="https://www.bnl.gov/about/history/firstvideo.php" target="_blank" rel="noreferrer">Brookhaven National Laboratory：The First Video Game?</a></td></tr><tr><td>1961〜1962</td><td>米国・MIT周辺</td><td>Spacewar!</td><td>構想からPDP-1上の実装・共同改良へ。作品と利用者コミュニティを結び付けて読む。 <a href="https://www.computerhistory.org/pdp-1/spacewar/" target="_blank" rel="noreferrer">Computer History Museum：Spacewar!</a></td></tr><tr><td>1971 / 1972</td><td>米国・業務用</td><td>Computer Space / Pong</td><td>商業用の筐体で、入力・画面・ルール・硬貨投入を組み合わせる。 <a href="https://www.computerhistory.org/timeline/graphics-games/" target="_blank" rel="noreferrer">Computer History Museum：Graphics &amp; Games</a></td></tr><tr><td>1972</td><td>米国・家庭用</td><td>Magnavox Odyssey</td><td>家庭のテレビと、画面外のオーバーレイ等を組み合わせた製品。 <a href="https://americanhistory.si.edu/collections/object/nmah_1302004" target="_blank" rel="noreferrer">Smithsonian：Magnavox Odyssey Video Game Unit, 1972</a></td></tr><tr><td>1978〜1979</td><td>日本・業務用</td><td>スペースインベーダー</td><td>1978年の発表からブームへ。ゲームセンターに加え喫茶店などの遊ぶ場所も見る。 <a href="https://www.taito.co.jp/70th/history" target="_blank" rel="noreferrer">タイトー70周年：タイトーの歩み</a></td></tr><tr><td>1983</td><td>日本・家庭用</td><td>ファミリーコンピュータ</td><td>カセットを交換して別のゲームを遊ぶ。北米のNES展開とは時期を分ける。 <a href="https://www.nintendo.com/jp/famicom/history/index.html" target="_blank" rel="noreferrer">任天堂：ファミコン年表</a></td></tr><tr><td>1985</td><td>北米・家庭用</td><td>NES</td><td>1983年以降の北米市場の落ち込みと、その後の展開を地域別に読む。 <a href="https://www.computerhistory.org/timeline/graphics-games/" target="_blank" rel="noreferrer">Computer History Museum：Graphics &amp; Games</a></td></tr><tr><td>1989</td><td>日本での発売年・携帯機</td><td>ゲームボーイ</td><td>持ち運び・画面・電池という条件で、据置機とは異なる選択を考える。 <a href="https://www.nintendo.co.jp/corporate/history/index.html" target="_blank" rel="noreferrer">任天堂：会社の沿革</a></td></tr><tr><td>1993</td><td>日本・アーケード</td><td>バーチャファイター</td><td>MODEL1基板によるポリゴン表現。PC以外の3D描画の系譜を示す。 <a href="https://www.sega.jp/history/arcade/product/9122/" target="_blank" rel="noreferrer">セガ・アーケードゲームヒストリー：バーチャファイター</a></td></tr><tr><td>1993</td><td>PC</td><td>DOOM</td><td>作品・エンジン・レベルデータ・改造を考える題材。最初のFPSとは扱わない。 <a href="https://bethesda.net/en-US/news/doom-turns-22" target="_blank" rel="noreferrer">Bethesda：DOOM Turns 22!</a></td></tr><tr><td>1994</td><td>日本での発売年・家庭用</td><td>PlayStation</td><td>3D表現とCD-ROMを、制作・容量・読込み・遊びの変化に接続する。 <a href="https://www.playstation.com/en-us/playstation-history/1994-ps-one/" target="_blank" rel="noreferrer">PlayStation：1994の歴史</a></td></tr><tr><td>1996</td><td>PC</td><td>Quake</td><td>3D世界、対戦、コミュニティ。初版とGLQuake・QuakeWorld等の時点を分ける。 <a href="https://bethesda.net/en-US/news/celebrating-25-years-of-quake" target="_blank" rel="noreferrer">Bethesda：Celebrating 25 years of Quake</a></td></tr><tr><td>1998</td><td>日本での発売年・家庭用</td><td>Dreamcast</td><td>モデム標準装備と家庭用機のネットワーク。個々のサービス開始日は別に確認する。 <a href="https://www.sega.jp/history/hard/dreamcast/" target="_blank" rel="noreferrer">セガハード大百科：ドリームキャスト</a></td></tr><tr><td>2001</td><td>PC向け製品の導入記録</td><td>GeForce3</td><td>プログラマブルシェーダの具体例。専用基板・家庭用機等の描画史と並べる。 <a href="https://www.nvidia.com/content/timeline/time_01.html" target="_blank" rel="noreferrer">NVIDIA Corporate Timeline：2001</a></td></tr><tr><td>2003</td><td>PC・配信基盤</td><td>Steam</td><td>Valveの公式冊子は2003年の公開と更新配信の目的を記録。デジタル配信全体の起点とはしない。 <a href="https://media.steampowered.com/apps/valve/2022/steamDeck_booklet_EN.pdf" target="_blank" rel="noreferrer">Valve：Steam Deck Booklet</a></td></tr><tr><td>2008</td><td>スマートフォン・ストア</td><td>App Store</td><td>配信・決済と携帯端末をつなぐ例。携帯電話ゲームの始まりとはしない。 <a href="https://www.apple.com/newsroom/2018/07/app-store-turns-10/" target="_blank" rel="noreferrer">Apple：The App Store turns 10</a></td></tr><tr><td>2009 / 2011</td><td>スウェーデン発・PC</td><td>Minecraft</td><td>初公開と正式版を区別し、プレイヤーによる制作・共有を読む。 <a href="https://www.minecraft.net/en-us/about-minecraft" target="_blank" rel="noreferrer">Minecraft：What is Minecraft?</a></td></tr><tr><td>2011</td><td>PC/Mac・運営</td><td>Team Fortress 2の基本プレイ無料化</td><td>販売方法の変更と継続更新の事例。F2Pやオンライン運営の起源とはしない。 <a href="https://store.steampowered.com/oldnews/5721?l=english" target="_blank" rel="noreferrer">Valve：Team Fortress 2 is now Free to Play</a></td></tr><tr><td>2015</td><td>制作環境</td><td>UE4の無料利用への変更発表</td><td>エンジン・ツールへのアクセスを考える。当時の発表を現在の利用条件として使わない。 <a href="https://www.unrealengine.com/en-US/blog/ue4-is-free" target="_blank" rel="noreferrer">Epic：If You Love Something, Set It Free</a></td></tr><tr><td>2016</td><td>米国・カナダの発売発表</td><td>PlayStation VR</td><td>家庭向けVR展開の一例。VRそのものの誕生年とはしない。 <a href="https://sony.mediaroom.com/2016-10-13-PlayStation-Makes-Virtual-Reality-Mainstream-With-Launch-Of-PlayStation-VR-Across-The-U-S-And-Canada" target="_blank" rel="noreferrer">Sony：2016年の北米PS VR発売発表</a></td></tr><tr><td>2017</td><td>日本のメーカー沿革</td><td>Nintendo Switch</td><td>テレビと携帯の利用場面を行き来する設計の例。 <a href="https://www.nintendo.co.jp/corporate/history/index.html" target="_blank" rel="noreferrer">任天堂：会社の沿革</a></td></tr></tbody></table><h2 id="annual-highlights" tabindex="-1">各年の代表的ソフトとハード <a class="header-anchor" href="#annual-highlights" aria-label="Permalink to &quot;各年の代表的ソフトとハード {#annual-highlights}&quot;">​</a></h2>',21)),i(r),e[1]||(e[1]=t('<h2 id="技術の章とのつながり" tabindex="-1">技術の章とのつながり <a class="header-anchor" href="#技術の章とのつながり" aria-label="Permalink to &quot;技術の章とのつながり&quot;">​</a></h2><table tabindex="0"><thead><tr><th>観点</th><th>関連する知識</th><th>分野</th></tr></thead><tbody><tr><td>容量の制約と表現</td><td>ROM/RAM、データ圧縮、スプライト・タイル、ロードとストリーミング</td><td><a href="/study/data/">data/</a> / <a href="/study/hardware/">hardware/</a> / <a href="/study/runtime/memory/">runtime/memory/</a></td></tr><tr><td>2D/3Dと遊びの設計</td><td>座標・カメラ、可視判定、メッシュ、UV、アニメーション、入力</td><td><a href="/study/graphics/">graphics/</a> / <a href="/study/math/">math/</a> / <a href="/study/game/">game/</a></td></tr><tr><td>PCと専用ハード</td><td>CPU、OS、driver、graphics API、shader、開発環境</td><td><a href="/study/hardware/">hardware/</a> / <a href="/study/os/">os/</a> / <a href="/study/graphics/api/comparison.html">graphics/api/</a></td></tr><tr><td>共有・対戦・継続運営</td><td>ネットワーク、状態同期、保存・互換、更新、ログ・計測</td><td><a href="/study/network/">network/</a> / <a href="/study/game/">game/</a> / <a href="/study/tools/">tools/</a></td></tr><tr><td>制作と小規模開発</td><td>エンジン、IDE、シェル、Python、アセット、Git・CI、ツールの条件</td><td><a href="/study/tools/">tools/</a> / <a href="/study/languages/">languages/</a> / <a href="/study/game/">game/</a></td></tr><tr><td>保存と研究</td><td>ソース・ビルド、コンパイラ、OS、機種、入力・表示、証言と史料</td><td><a href="/study/compilers/">compilers/</a> / <a href="/study/os/">os/</a> / <a href="/study/data/">data/</a> / <a href="/study/history/">history/</a></td></tr></tbody></table><p>描画技術の各論は、<a href="/study/guide/rendering/timeline.html">リアルタイム3D技術全史</a>からも参照できます。</p><h2 id="理解を確かめる問い" tabindex="-1">理解を確かめる問い <a class="header-anchor" href="#理解を確かめる問い" aria-label="Permalink to &quot;理解を確かめる問い&quot;">​</a></h2><ol><li>自分が選んだ作品で、技術的な制約が遊びのルールに表れている箇所を一つ挙げられるか。</li><li>同じ年代の家庭用機・携帯機・PC・アーケードを比べ、性能以外の設計条件を説明できるか。</li><li>媒体の容量、実行時のメモリ容量、読込み速度を分けて考えられるか。</li><li>ゲーム本体、データ、エンジン、MOD、配信基盤、運営サーバの役割を区別できるか。</li><li>ある「世界初」という主張は、何を範囲・条件としたものか確認できるか。</li><li>10年後に自作ゲームを調べ直すなら、何をどの版情報とともに残すか。</li></ol><h3 id="小さな調査課題" tabindex="-1">小さな調査課題 <a class="header-anchor" href="#小さな調査課題" aria-label="Permalink to &quot;小さな調査課題&quot;">​</a></h3><p>好きな作品を一つ選び、原作の発売地域・機種・年、入力、媒体、開発環境、遊ぶ場所、保存に必要なものを1枚にまとめます。メーカー資料と当時の資料を一つずつ探し、事実・証言・自分の解釈を分けて書きます。</p><h2 id="参考資料と確認範囲" tabindex="-1">参考資料と確認範囲 <a class="header-anchor" href="#参考資料と確認範囲" aria-label="Permalink to &quot;参考資料と確認範囲&quot;">​</a></h2><ul><li><a href="https://www.bnl.gov/about/history/firstvideo.php" target="_blank" rel="noreferrer">Brookhaven National Laboratory：The First Video Game?</a></li><li><a href="https://www.computerhistory.org/pdp-1/spacewar/" target="_blank" rel="noreferrer">Computer History Museum：Spacewar!</a></li><li><a href="https://www.computerhistory.org/timeline/graphics-games/" target="_blank" rel="noreferrer">Computer History Museum：Graphics &amp; Games</a></li><li><a href="https://americanhistory.si.edu/collections/object/nmah_1302004" target="_blank" rel="noreferrer">Smithsonian：Magnavox Odyssey Video Game Unit, 1972</a></li><li><a href="https://www.taito.co.jp/70th/history" target="_blank" rel="noreferrer">タイトー70周年：タイトーの歩み</a></li><li><a href="https://www.nintendo.com/jp/famicom/history/index.html" target="_blank" rel="noreferrer">任天堂：ファミコン年表</a></li><li><a href="https://www.nintendo.co.jp/corporate/history/index.html" target="_blank" rel="noreferrer">任天堂：会社の沿革</a></li><li><a href="https://www.sega.jp/history/arcade/product/9122/" target="_blank" rel="noreferrer">セガ・アーケードゲームヒストリー：バーチャファイター</a></li><li><a href="https://bethesda.net/en-US/news/doom-turns-22" target="_blank" rel="noreferrer">Bethesda：DOOM Turns 22!</a></li><li><a href="https://github.com/id-Software/DOOM" target="_blank" rel="noreferrer">id Software：DOOM公開ソース</a></li><li><a href="https://www.playstation.com/en-us/playstation-history/1994-ps-one/" target="_blank" rel="noreferrer">PlayStation：1994の歴史</a></li><li><a href="https://bethesda.net/en-US/news/celebrating-25-years-of-quake" target="_blank" rel="noreferrer">Bethesda：Celebrating 25 years of Quake</a></li><li><a href="https://github.com/id-Software/Quake" target="_blank" rel="noreferrer">id Software：Quake公開ソース</a></li><li><a href="https://www.sega.jp/history/hard/dreamcast/" target="_blank" rel="noreferrer">セガハード大百科：ドリームキャスト</a></li><li><a href="https://www.nvidia.com/content/timeline/time_01.html" target="_blank" rel="noreferrer">NVIDIA Corporate Timeline：2001</a></li><li><a href="https://media.steampowered.com/apps/valve/2022/steamDeck_booklet_EN.pdf" target="_blank" rel="noreferrer">Valve：Steam Deck Booklet</a></li><li><a href="https://www.apple.com/newsroom/2018/07/app-store-turns-10/" target="_blank" rel="noreferrer">Apple：The App Store turns 10</a></li><li><a href="https://www.minecraft.net/en-us/about-minecraft" target="_blank" rel="noreferrer">Minecraft：What is Minecraft?</a></li><li><a href="https://store.steampowered.com/oldnews/5721?l=english" target="_blank" rel="noreferrer">Valve：Team Fortress 2 is now Free to Play</a></li><li><a href="https://www.nexon.co.jp/en/ir/uploads/sokai20140325e.pdf" target="_blank" rel="noreferrer">Nexon：2014年公式IR資料</a></li><li><a href="https://www.unrealengine.com/en-US/blog/ue4-is-free" target="_blank" rel="noreferrer">Epic：If You Love Something, Set It Free</a></li><li><a href="https://sony.mediaroom.com/2016-10-13-PlayStation-Makes-Virtual-Reality-Mainstream-With-Launch-Of-PlayStation-VR-Across-The-U-S-And-Canada" target="_blank" rel="noreferrer">Sony：2016年の北米PS VR発売発表</a></li><li><a href="https://www.loc.gov/preservation/resources/rfs/software-videogames.html" target="_blank" rel="noreferrer">Library of Congress：Software and Video Games保存推奨形式</a></li></ul><h3 id="資料の扱い" tabindex="-1">資料の扱い <a class="header-anchor" href="#資料の扱い" aria-label="Permalink to &quot;資料の扱い&quot;">​</a></h3><p>メーカー自身の記録・原作者公開ソース、博物館の調査・所蔵資料、公的保存指針を区別して参照。</p><p>Steamの公式資料：公式PDFの検索索引で2003年の公開と目的を確認。全文直接取得は未完了。</p>',12))])}const g=a(d,[["render",l]]);export{w as __pageData,g as default};
